import{_ as r,C as o,c as s,o as l,aj as d,j as t,G as a,a as h,w as c}from"./chunks/framework.Bfdr4H5E.js";const p="/sk/images/TradingView-Trend-Line-Tools.webp",g="/sk/images/TradingView-Trendline-AB1.webp",w="/sk/images/TradingView-Trendline-AB2.webp",u="/sk/images/TradingView-Anchored-VWAP-tool.webp",m="/sk/images/TradingView-1Fixed-Range-Volume-Profile.webp",f="/sk/images/TradingView-2Fixed-Range-Volume-Profile.webp",x=JSON.parse('{"title":"TradingView – How to use Drawing Tools ?","description":"","frontmatter":{"outline":"deep","prev":{"text":"TradingView – Chart Area Basics & Settings","link":"/trading-with-pav/tradingview-chart-area-basics-settings"},"next":{"text":"TradingView – Indicators","link":"/trading-with-pav/tradingview-indicators"}},"headers":[],"relativePath":"trading-with-pav/tradingview-how-to-use-drawing-tools.md","filePath":"trading-with-pav/tradingview-how-to-use-drawing-tools.md"}'),y={name:"trading-with-pav/tradingview-how-to-use-drawing-tools.md"};function b(T,e,v,A,k,V){const n=o("GraphComment"),i=o("ClientOnly");return l(),s("div",null,[e[0]||(e[0]=d('<h1 id="tradingview-–-how-to-use-drawing-tools" tabindex="-1">TradingView – How to use Drawing Tools ? <a class="header-anchor" href="#tradingview-–-how-to-use-drawing-tools" aria-label="Permalink to &quot;TradingView – How to use Drawing Tools ?&quot;">​</a></h1><p>In this article “TradingView – How to use Drawing Tools?” we are gonna take a look on drawing panel and learn the basics of how to draw or plot any Support/Resistance or Supply Demand Zones.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#how-to-draw">How to draw ?</a><ul><li><a href="#candle-base-plot">Candle Base Plot</a></li><li><a href="#time-base-plot">Time Base Plot</a></li></ul></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><p>As we learned in <a href="/sk/trading-with-pav/charting-platform/">Charting Platform</a> the drawing panel or left side menu has <strong>Cursors</strong>, <strong>Trend Line Tools</strong>, <strong>Gann and Fibonacci Tools</strong>, <strong>Geometric Shapes</strong>, <strong>Annotation Tools</strong>, <strong>Patterns and Prediction and Measurement Tools</strong>. If we total all the drawing tools from the menus the total will be roughly 85 drawing tools although will be using not more than 10 tools as they are not that important but will teach you how to draw all of them.</p><h2 id="how-to-draw" tabindex="-1">How to draw ? <a class="header-anchor" href="#how-to-draw" aria-label="Permalink to &quot;How to draw ?&quot;">​</a></h2><p>As you should know by now that drawing in trading is not for artistic reasons but for analyzing the chart to predict if price is going Up, Down or Sideways. Most of the drawing tools are plotted on candle and very few of the drawing tools are time based. Basically,</p><p><strong>There are two types of Drawing method</strong></p><ol><li>Candle Base Plot.</li><li>Time Base Plot.</li></ol><p>Lets look at both of these:</p><h3 id="candle-base-plot" tabindex="-1">Candle Base Plot <a class="header-anchor" href="#candle-base-plot" aria-label="Permalink to &quot;Candle Base Plot&quot;">​</a></h3><p>Almost majority of the drawing tools fall under this category. In the method whatever drawing tool you select there are points to plot e.g. to draw a line you would require two points for triangle 3 points or for rectangle 4 points etc. So in trading chart these points are candle’s OHLC.</p><p>If its Trend Line you use 1st point on the candle you 1st selected then 2nd point on another candle be it forward or backward from the 1st selected candle point.</p><p>Lets take a looks at an example in which we have to draw a trend line on two candles High.<br> So lets open “<strong>Trend Line Tools</strong>” and select “<strong>Trend Line</strong>“.</p><p><img src="'+p+'" alt="TradingView-Trend-Line-Tools"></p><p>In the image below you can see we have marked Candle A and B to draw a trend line.</p><p><img src="'+g+'" alt="TradingView-Trendline-AB1"></p><p>High of candle A is 588.25 and B is 586.45. So now you put your cursor above the high of candle A and click then move the mouse to high of B and click again plotting the trend line successfully or did you really put the both points at correct spot most likely not. Although high accuracy in trading is subjective but accuracy can be achieved in TradingView and that is with Magnet mode.</p><p><strong>Magnet Mode</strong> – Magnet Mode snaps Drawings placed near price bars to the closest OHLC value. There are two types of mode in Magnet for snaping the drawing</p><ol><li><strong>Weak Magnet</strong> – Weak Magnet pulls the drawing points to chart values (bars) when you are drawing near them.</li><li><strong>Strong Magnet</strong> – Strong Magnet pulls the drawing points to chart values (bars), regardless of the distance between the points and chart values.</li></ol><p><strong>Tip</strong> – You don’t have to keep the magnet active all the time instead pressing CTRL when drawing will activate it temporary.</p><p>Lets now try again with the example above this time with Magnet CTRL key method.</p><ol><li>To snap to a high of a candle you have to activate Trendline and just hover your mouse over the high of the candle without getting close to the high itself and press CTRL key the cursor will automatically snap to the high.</li><li>After it snaps just click and then move the cursor to 2nd Candle high and press CTRL the cursor snaps you click and voila you just plotted a trendline accurately.</li></ol><p><img src="'+w+'" alt="TradingView-Trendline-AB2"></p><p>In the above image the top blue line is the example we discuss above. Then the purple line is “<strong>Horizontal line</strong>” from “<strong>Trend Line tools</strong>” it has only one point, in the image you can see blue arrow on the bullish candle closing. Then there is another orange color “<strong>Trend Line</strong>” plotted on bullish candles open and second point at bearish candle close.</p><p>Whenever you draw from any tool you get a floating option of the drawn tool, in that you can change the settings of the tool. You can even select any of the drawings by hovering over it and selecting it and go and change the settings like e.g. changing the line color width etc.</p><p>All the drawing tools same concept. Will learn some of them in this course articles later. Now lets learn about second drawing method below.</p><h3 id="time-base-plot" tabindex="-1">Time Base Plot <a class="header-anchor" href="#time-base-plot" aria-label="Permalink to &quot;Time Base Plot&quot;">​</a></h3><p>These types of drawings are rare or very few of them. That’s because of instead of using OHLC points these drawings are time based as in they depend on the time or day. So in short when you place 1st point you are going for X – axis location.</p><p>Let’s look at an example of one such drawing tool called as “<strong>Anchored VWAP</strong>“. I want to plot this on SBIN 15 min chart on the opening candle of 05 May 2023. Then I would follow as below.</p><p>Open SBIN 15 min chart and locate 05 May 2023 through “<strong>Go to</strong>” (ALT + G). Then open the “<strong>Trend Line Tools</strong>” and select “<strong>Anchored VWAP</strong>“. After that move the cursor to 05 May 2023 9:15 am and cursor can be vertically any where it doesn’t need to be on the candle precise. When clicked “<strong>Anchored VWAP</strong>” is plotted as shown in the image below.</p><p><img src="'+u+'" alt="TradingView-Anchored-VWAP-tool"></p><p>As you can see in the above image “<strong>Anchored VWAP</strong>” point is not in on any of the candle’s OHLC points and not even in the middle of the candle or the body. And the end point is to the right side of the chart i.e. 12th May 2023 which the market closed @3:30 pm on Friday. It means that the end point for “<strong>Anchored VWAP</strong>” will always keep plotting when markets are open.</p><p>At this point you wouldn’t understand “<strong>Anchored VWAP</strong>” but still I will try to explain what is happening.</p><p>**What is Anchored VWAP?<br> **Anchored VWAP displays the volume-weighted average price for a specific time period, starting from a user-selected point. In other words, Anchored VWAP shows the price of an asset adjusted for its volume starting from any point chosen on the chart. This is a powerful tool because it takes into account the number of shares traded at each price level and presents it as a smooth line.</p><p>Now if you understand the above definition of “<strong>Anchored VWAP</strong>” then that’s exactly what has happened in the above chart. On the starting point 05 May 09:15 am the first point that is on the candle is because it calculated the candles volume and placed on volume location on the price axis i.e. Y-axis. So the center line in blue color is the VWAP line till the end of the market. And is plotted according to volume traded at each price level.</p><p>Lets look at one more example of Time base plot a “<strong>Fixed Range Volume Profile</strong>” which has 2 points.</p><p>lets say we want to analyze where the volumes have accumulated from 02 May 23 to 05 May 23 on SBIN 15 min chart.</p><p>From the drawing(left menu) go to the “<strong>Prediction and Measurement Tools</strong>” and select “<strong>Fixed Range Volume Profile</strong>“. You will see “<strong>Click to set a point</strong>” message on the bottom center of the chart. After that move your cursor anywhere at vertical axis on 02 May 23 @9:15 am and click to conform.</p><p><img src="'+m+'" alt="TradingView-1Fixed-Range-Volume-Profile"></p><p>Now again move your cursor anywhere at vertical axis on 05 May 23 @3:15 pm and click to conform. The above image shows this process setting the second point. The below image shows the result of the plot.</p><p><img src="'+f+'" alt="TradingView-2Fixed-Range-Volume-Profile"></p><p>As you can see above the 1st and 2nd point on the chart defined the left-right points which automatically expanded to the high (Red down pointing arrow in image) and low (Blue up pointing arrow in image) of the defined area i.e. 02 May 23 to 05 May 23.</p><p>That’s all for drawing tools now you should be able to draw any of the drawing tools. Will learn some of the needed drawing tools later in our course. In the next article will learn about Indicators on what are they and how to apply them.</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',44)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/VPzcOvxCBSQ",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[h("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),a(i,null,{default:c(()=>[a(n)]),_:1})])}const C=r(y,[["render",b]]);export{x as __pageData,C as default};
